functions.compute_bmi:
CREATE OR REPLACE FUNCTION public.compute_bmi()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.weight IS NOT NULL AND NEW.height IS NOT NULL THEN
    NEW.bmi := NEW.weight / POWER(NEW.height / 100, 2);
  END IF;
  RETURN NEW;
END;
$function$

functions.rpc_get_expenses:
CREATE OR REPLACE FUNCTION public.rpc_get_expenses(p_requester_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_page integer DEFAULT 1, p_items_per_page integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_offset integer;
  v_total integer;
  v_rows jsonb;
begin
  select clinic_id into v_clinic_id
  from public.users_metadata
  where id = p_requester_id and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic';
  end if;

  v_offset := greatest((p_page - 1) * p_items_per_page, 0);

  select count(*) into v_total
  from public.clinic_expenses e
  where e.clinic_id = v_clinic_id
    and (p_start_date is null or e.spent_at >= p_start_date)
    and (p_end_date is null or e.spent_at <= p_end_date);

  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  into v_rows
  from (
    select
      e.id,
      e.clinic_id,
      e.category,
      e.amount,
      e.notes,
      e.spent_at,
      e.created_at
    from public.clinic_expenses e
    where e.clinic_id = v_clinic_id
      and (p_start_date is null or e.spent_at >= p_start_date)
      and (p_end_date is null or e.spent_at <= p_end_date)
    order by e.spent_at desc
    limit p_items_per_page
    offset v_offset
  ) t;

  return jsonb_build_object(
    'expenses', v_rows,
    'total', v_total,
    'page', p_page,
    'itemsPerPage', p_items_per_page
  );
end;
$function$

functions.rpc_get_messages:
CREATE OR REPLACE FUNCTION public.rpc_get_messages(p_requester_id uuid, p_conversation_id uuid, p_limit integer DEFAULT 50, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_allowed boolean;
  v_rows jsonb;
begin
  select clinic_id into v_clinic_id
  from public.users_metadata
  where id = p_requester_id and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic';
  end if;

  select exists (
    select 1
    from public.clinic_conversation_members m
    join public.clinic_conversations c on c.id = m.conversation_id
    where m.conversation_id = p_conversation_id
      and m.user_id = p_requester_id
      and c.clinic_id = v_clinic_id
  ) into v_allowed;

  if coalesce(v_allowed, false) = false then
    raise exception 'Conversation not found or access denied';
  end if;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at asc), '[]'::jsonb)
  into v_rows
  from (
    select
      msg.id,
      msg.conversation_id,
      msg.sender_id,
      um.full_name as sender_name,
      msg.body,
      msg.created_at,
      msg.edited_at
    from public.clinic_messages msg
    join public.users_metadata um on um.id = msg.sender_id
    where msg.conversation_id = p_conversation_id
      and (p_before is null or msg.created_at < p_before)
    order by msg.created_at desc
    limit greatest(coalesce(p_limit, 50), 1)
  ) t;

  return v_rows;
end;
$function$

functions.rpc_send_message:
CREATE OR REPLACE FUNCTION public.rpc_send_message(p_requester_id uuid, p_conversation_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_conv_clinic uuid;
  v_allowed boolean;
  v_id uuid;
begin
  select clinic_id into v_clinic_id
  from public.users_metadata
  where id = p_requester_id and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic';
  end if;

  select c.clinic_id into v_conv_clinic
  from public.clinic_conversations c
  where c.id = p_conversation_id
  limit 1;

  if v_conv_clinic is null or v_conv_clinic <> v_clinic_id then
    raise exception 'Conversation not found or access denied';
  end if;

  select exists (
    select 1 from public.clinic_conversation_members m
    where m.conversation_id = p_conversation_id and m.user_id = p_requester_id
  ) into v_allowed;

  if coalesce(v_allowed, false) = false then
    raise exception 'Conversation not found or access denied';
  end if;

  insert into public.clinic_messages (clinic_id, conversation_id, sender_id, body, created_at)
  values (v_clinic_id, p_conversation_id, p_requester_id, btrim(p_body), now())
  returning id into v_id;

  update public.clinic_conversations
  set updated_at = now()
  where id = p_conversation_id;

  return v_id;
end;
$function$

