functions.generate_clinic_license:
CREATE OR REPLACE FUNCTION public.generate_clinic_license(p_tier_plan text, p_max_doctors integer, p_max_assistants integer, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_license_id uuid;
  v_license_key text;
  v_payload bytea;
  v_payload_json text;
begin
  v_payload_json := json_build_object(
    'tier_plan', p_tier_plan,
    'doctors_limit', p_max_doctors,
    'assistants_limit', p_max_assistants
  )::text;

  v_payload := convert_to(v_payload_json, 'utf8');

  loop
    v_license_key := upper(
      substring(encode(digest(v_payload || gen_random_bytes(16), 'sha256'), 'hex') from 1  for 5) || '-' ||
      substring(encode(digest(v_payload || gen_random_bytes(16), 'sha256'), 'hex') from 6  for 5) || '-' ||
      substring(encode(digest(v_payload || gen_random_bytes(16), 'sha256'), 'hex') from 11 for 5) || '-' ||
      substring(encode(digest(v_payload || gen_random_bytes(16), 'sha256'), 'hex') from 16 for 5) || '-' ||
      substring(encode(digest(v_payload || gen_random_bytes(16), 'sha256'), 'hex') from 21 for 5)
    );

    begin
      insert into public.licenses (
        license_key,
        payload,
        expires_at,
        revoked,
        created_at
      )
      values (
        v_license_key,
        v_payload,
        p_expires_at,
        false,
        now()
      )
      returning id into v_license_id;

      exit;
    exception
      when unique_violation then
        -- retry
    end;
  end loop;

  return v_license_id;
end;
$function$

functions.rpc_create_staff_invite:
CREATE OR REPLACE FUNCTION public.rpc_create_staff_invite(p_requester_id uuid, p_email text, p_user_type user_type_enum, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_is_admin boolean;
  v_invite_id uuid;
  v_current_count integer;
  v_max_allowed integer;
begin
  select clinic_id
  into v_clinic_id
  from public.users_metadata
  where id = p_requester_id
    and active = true
    and user_type = 'doctor'
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic or is not a doctor';
  end if;

  select exists (
    select 1
    from public.clinics
    where id = v_clinic_id
      and admin_id = p_requester_id
  )
  into v_is_admin;

  if not v_is_admin then
    raise exception 'Only clinic admin can invite staff';
  end if;

  if p_user_type = 'doctor' then
    select count(*)
    into v_current_count
    from public.users_metadata
    where clinic_id = v_clinic_id
      and user_type = 'doctor';

    select max_doctors
    into v_max_allowed
    from public.clinics
    where id = v_clinic_id;
  else
    select count(*)
    into v_current_count
    from public.users_metadata
    where clinic_id = v_clinic_id
      and user_type = 'assistant';

    select max_assistants
    into v_max_allowed
    from public.clinics
    where id = v_clinic_id;
  end if;

  if v_current_count >= coalesce(v_max_allowed, 0) then
    raise exception 'Clinic limit reached for %', p_user_type;
  end if;

  insert into public.staff_invites (
    clinic_id,
    email,
    user_type,
    invited_by,
    token_hash,
    expires_at,
    created_at
  )
  values (
    v_clinic_id,
    lower(trim(p_email)),
    p_user_type,
    p_requester_id,
    p_token_hash,
    p_expires_at,
    now()
  )
  returning id into v_invite_id;

  return v_invite_id;
end;
$function$

functions.rpc_get_patient_medical:
CREATE OR REPLACE FUNCTION public.rpc_get_patient_medical(p_requester_id uuid, p_patient_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_patient jsonb;
  v_medical jsonb;
  v_latest_measurement jsonb;
begin
  select clinic_id
  into v_clinic_id
  from public.users_metadata
  where id = p_requester_id
    and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic';
  end if;

  select to_jsonb(p)
  into v_patient
  from public.patients p
  where p.id = p_patient_id
    and p.clinic_id = v_clinic_id
  limit 1;

  if v_patient is null then
    raise exception 'Patient not found or access denied';
  end if;

  select to_jsonb(mi)
  into v_medical
  from public.patient_medical_info mi
  where mi.patient_id = p_patient_id
  limit 1;

  select to_jsonb(pm)
  into v_latest_measurement
  from public.patient_measurements pm
  where pm.patient_id = p_patient_id
  order by pm.recorded_at desc
  limit 1;

  return jsonb_build_object(
    'patient', coalesce(v_patient, 'null'::jsonb),
    'medical_info', coalesce(v_medical, 'null'::jsonb),
    'latest_measurement', coalesce(v_latest_measurement, 'null'::jsonb)
  );
end;
$function$

functions.enforce_single_user_type:
CREATE OR REPLACE FUNCTION public.enforce_single_user_type()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_table_name = 'doctor_profiles' then
    if exists (
      select 1
      from public.assistant_profiles ap
      where ap.id = new.id
    ) then
      raise exception 'A user cannot be both doctor and assistant';
    end if;

    if not exists (
      select 1
      from public.users_metadata um
      where um.id = new.id
        and um.user_type = 'doctor'
    ) then
      raise exception 'doctor_profiles.id must reference users_metadata with user_type = doctor';
    end if;

  elsif tg_table_name = 'assistant_profiles' then
    if exists (
      select 1
      from public.doctor_profiles dp
      where dp.id = new.id
    ) then
      raise exception 'A user cannot be both doctor and assistant';
    end if;

    if not exists (
      select 1
      from public.users_metadata um
      where um.id = new.id
        and um.user_type = 'assistant'
    ) then
      raise exception 'assistant_profiles.id must reference users_metadata with user_type = assistant';
    end if;
  end if;

  return new;
end;
$function$

