CREATE OR REPLACE FUNCTION public.rpc_create_virtual_clinic(p_requester_id uuid, p_speciality_id uuid, p_doctor_id uuid DEFAULT NULL::uuid, p_active boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_is_admin boolean;
  v_virtual_clinic_id uuid;
begin
  select clinic_id
  into v_clinic_id
  from public.users_metadata
  where id = p_requester_id
    and active = true
    and user_type = 'doctor'
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic or is not a doctor';
  end if;

  select exists (
    select 1
    from public.clinics
    where id = v_clinic_id
      and admin_id = p_requester_id
  )
  into v_is_admin;

  if not v_is_admin then
    raise exception 'Only clinic admin can create virtual clinics';
  end if;

  if not exists (
    select 1
    from public.doctor_specialities
    where id = p_speciality_id
  ) then
