    doctor_id,
    created_by_admin,
    active,
    created_at,
    updated_at
  )
  values (
    v_clinic_id,
    p_speciality_id,
    p_doctor_id,
    p_requester_id,
    p_active,
    now(),
    now()
  )
  returning id into v_virtual_clinic_id;

  return v_virtual_clinic_id;
end;
