functions.rpc_cleanup_expired_invites:
CREATE OR REPLACE FUNCTION public.rpc_cleanup_expired_invites()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_activation_deleted integer;
  v_staff_deleted integer;
begin
  delete from public.clinic_activation_links
  where used_at is null
    and expires_at < now();

  get diagnostics v_activation_deleted = row_count;

  delete from public.staff_invites
  where accepted_at is null
    and expires_at < now();

  get diagnostics v_staff_deleted = row_count;

  return jsonb_build_object(
    'clinic_activation_links_deleted', v_activation_deleted,
    'staff_invites_deleted', v_staff_deleted
  );
end;
$function$

functions.rpc_get_staff_invite_status:
CREATE OR REPLACE FUNCTION public.rpc_get_staff_invite_status(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
begin
  select
    si.*,
    c.name as clinic_name
  into v_row
  from public.staff_invites si
  join public.clinics c on c.id = si.clinic_id
  where si.token_hash = p_token_hash
  limit 1;

  if v_row.id is null then
    return jsonb_build_object(
      'valid', false,
      'reason', 'not_found'
    );
  end if;

  if v_row.accepted_at is not null then
    return jsonb_build_object(
      'valid', false,
      'reason', 'already_accepted'
    );
  end if;

  if v_row.expires_at <= now() then
    return jsonb_build_object(
      'valid', false,
      'reason', 'expired'
    );
  end if;

  return jsonb_build_object(
    'valid', true,
    'email', v_row.email,
    'user_type', v_row.user_type,
    'clinic_id', v_row.clinic_id,
    'clinic_name', v_row.clinic_name
  );
end;
$function$

functions.enforce_clinic_admin_is_doctor:
CREATE OR REPLACE FUNCTION public.enforce_clinic_admin_is_doctor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.admin_id is not null then
    if not exists (
      select 1
      from public.users_metadata um
      where um.id = new.admin_id
        and um.user_type = 'doctor'
    ) then
      raise exception 'Clinic admin must be a doctor';
    end if;

    if not exists (
      select 1
      from public.doctor_profiles dp
      where dp.id = new.admin_id
    ) then
      raise exception 'Clinic admin must exist in doctor_profiles';
    end if;
  end if;

  return new;
end;
$function$

functions.rpc_get_activation_link_status:
CREATE OR REPLACE FUNCTION public.rpc_get_activation_link_status(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_payload_json jsonb;
begin
  select
    cal.*,
    l.payload,
    l.revoked,
    l.used_by
  into v_row
  from public.clinic_activation_links cal
  join public.licenses l on l.id = cal.license_id
  where cal.token_hash = p_token_hash
  limit 1;

  if v_row.id is null then
    return jsonb_build_object(
      'valid', false,
      'reason', 'not_found'
    );
  end if;

  if v_row.used_at is not null then
    return jsonb_build_object(
      'valid', false,
      'reason', 'already_used'
    );
  end if;

  if v_row.expires_at <= now() then
    return jsonb_build_object(
      'valid', false,
      'reason', 'expired'
    );
  end if;

  if v_row.revoked = true then
    return jsonb_build_object(
      'valid', false,
      'reason', 'license_revoked'
    );
  end if;

  if v_row.used_by is not null then
    return jsonb_build_object(
      'valid', false,
      'reason', 'license_already_used'
    );
  end if;

  v_payload_json := convert_from(v_row.payload, 'utf8')::jsonb;

  return jsonb_build_object(
    'valid', true,
    'email', v_row.email,
    'tier_plan', v_payload_json->>'tier_plan',
    'doctors_limit', coalesce((v_payload_json->>'doctors_limit')::int, 0),
    'assistants_limit', coalesce((v_payload_json->>'assistants_limit')::int, 0)
  );
end;
$function$

functions.rpc_get_clinic_dashboard_counts:
CREATE OR REPLACE FUNCTION public.rpc_get_clinic_dashboard_counts(p_requester_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
begin
  select clinic_id
  into v_clinic_id
  from public.users_metadata
  where id = p_requester_id
    and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic';
  end if;

  return jsonb_build_object(
    'patients', (
      select count(*) from public.patients where clinic_id = v_clinic_id
    ),
    'doctors', (
      select count(*) from public.users_metadata where clinic_id = v_clinic_id and user_type = 'doctor'
    ),
    'assistants', (
      select count(*) from public.users_metadata where clinic_id = v_clinic_id and user_type = 'assistant'
    ),
    'virtual_clinics', (
      select count(*) from public.virtual_clinics where clinic_id = v_clinic_id
    ),
    'appointments_total', (
      select count(*) from public.appointments where clinic_id = v_clinic_id
    ),
    'appointments_pending', (
      select count(*) from public.appointments where clinic_id = v_clinic_id and status = 'pending'
    ),
    'payments_total', (
      select count(*) from public.payments where clinic_id = v_clinic_id
    ),
    'payments_paid', (
      select count(*) from public.payments where clinic_id = v_clinic_id and status = 'paid'
    )
  );
end;
$function$

functions.rpc_get_or_create_direct_conversation:
CREATE OR REPLACE FUNCTION public.rpc_get_or_create_direct_conversation(p_requester_id uuid, p_other_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_other_clinic_id uuid;
  v_existing uuid;
  v_new uuid;
begin
  select clinic_id into v_clinic_id
  from public.users_metadata
  where id = p_requester_id and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Requester has no clinic';
  end if;

  select clinic_id into v_other_clinic_id
  from public.users_metadata
  where id = p_other_user_id and active = true
  limit 1;

  if v_other_clinic_id is null or v_other_clinic_id <> v_clinic_id then
    raise exception 'Other user not found in clinic';
  end if;

  -- Find existing direct conversation with exactly these 2 users (best-effort)
  select c.id
  into v_existing
  from public.clinic_conversations c
  where c.clinic_id = v_clinic_id
    and c.kind = 'direct'
    and exists (
      select 1 from public.clinic_conversation_members m
      where m.conversation_id = c.id and m.user_id = p_requester_id
    )
    and exists (
      select 1 from public.clinic_conversation_members m
      where m.conversation_id = c.id and m.user_id = p_other_user_id
    )
  order by c.updated_at desc
  limit 1;

  if v_existing is not null then
    return v_existing;
  end if;

  insert into public.clinic_conversations (clinic_id, kind, title, created_by, created_at, updated_at)
  values (v_clinic_id, 'direct', null, p_requester_id, now(), now())
  returning id into v_new;

  insert into public.clinic_conversation_members (conversation_id, user_id, role, joined_at)
  values
    (v_new, p_requester_id, 'member', now()),
    (v_new, p_other_user_id, 'member', now())
  on conflict do nothing;

  return v_new;
end;
$function$

functions.enforce_users_metadata_type_profile_matc:
CREATE OR REPLACE FUNCTION public.enforce_users_metadata_type_profile_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.user_type = 'doctor' then
    if exists (
      select 1
      from public.assistant_profiles ap
      where ap.id = new.id
    ) then
      raise exception 'Doctor user cannot also exist in assistant_profiles';
    end if;
  elsif new.user_type = 'assistant' then
    if exists (
      select 1
      from public.doctor_profiles dp
      where dp.id = new.id
    ) then
      raise exception 'Assistant user cannot also exist in doctor_profiles';
    end if;
  end if;

  return new;
end;
$function$
